                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="19" name="question_19" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="19" name="question_19" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="19" name="question_19" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="19" name="question_19" value="D"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-20" class="ielts-q-badge">20</strong> <span>The idea of growing and eating unusual plants may not be accepted on a large scale.</span></td>
