INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1731, 173, 'reading', 'Reading Passage 1: The thylacine', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-5                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p><em>Complete the notes below.</em></p>
<p><em>Choose <strong>ONE WORD ONLY</strong> from the passage for each answer.</em></p>
<p><em>Write your answers in boxes on your answer sheet.</em></p>
<p class="ielts-reading-passage-subhead"><strong><strong>The thylacine</strong></strong></p>
<p><strong>Appearance and behaviour</strong></p>
<ul>
<li>looked rather like a dog</li>
<li>had a series of stripes along its body and tail</li>
<li>ate an entirely <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">1</strong><input type="text" data-qnum="1" name="question_1" class="ielts-inline-input" placeholder="[1] javob..." autocomplete="off" spellcheck="false"></span></span> diet</li>
<li>probably depended mainly on <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">2</strong><input type="text" data-qnum="2" name="question_2" class="ielts-inline-input" placeholder="[2] javob..." autocomplete="off" spellcheck="false"></span></span> when hunting</li>
<li>young spent first months of life inside its mother’s <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">3</strong><input type="text" data-qnum="3" name="question_3" class="ielts-inline-input" placeholder="[3] javob..." autocomplete="off" spellcheck="false"></span></span></li>
</ul>
<p><strong>Decline and extinction</strong></p>
<ul>
<li>last evidence in mainland Australia is a 3,100-year-old <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">4</strong><input type="text" data-qnum="4" name="question_4" class="ielts-inline-input" placeholder="[4] javob..." autocomplete="off" spellcheck="false"></span></span></li>
<li>probably went extinct in mainland Australia due to animals known as dingoes</li>
<li>reduction in <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">5</strong><input type="text" data-qnum="5" name="question_5" class="ielts-inline-input" placeholder="[5] javob..." autocomplete="off" spellcheck="false"></span></span> and available sources of food were partly responsible for decline in Tasmania</li>
</ul>
</div>                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-reading-question-item">
                                                                                                    
                                                                                                                                                                                                                                                                </div>
