-- Section 1733: Reading Passage 3: Building the Skyline: The Birth and Growth of Manhattan&rsquo;s Skyscrapers
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1733, 173, 'reading', 'Reading Passage 3: Building the Skyline: The Birth and Growth of Manhattan&rsquo;s Skyscrapers', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-31                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter, <strong>A</strong>, <strong>B</strong>, <strong>C</strong> or <strong>D</strong>.</p>
<p><em>Write the correct letter in boxes on your answer sheet.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="27"><div class="ielts-q-header"><strong class="ielts-q-badge">27</strong><span class="ielts-q-title"><span>What point does Shester make about Barr’s book in the first paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="A"><span class="ielts-radio-text"><strong>A</strong> It gives a highly original explanation for urban development.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="B"><span class="ielts-radio-text"><strong>B</strong> Elements of Barr’s research papers are incorporated throughout the book.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="C"><span class="ielts-radio-text"><strong>C</strong> Other books that are available on the subject have taken a different approach.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="D"><span class="ielts-radio-text"><strong>D</strong> It covers a range of factors that affected the development of New York.</span></label></div></div><div class="ielts-standalone-q" data-qnum="28"><div class="ielts-q-header"><strong class="ielts-q-badge">28</strong><span class="ielts-q-title"><span>How does Shester respond to the information in the book about tenements?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="A"><span class="ielts-radio-text"><strong>A</strong> She describes the reasons for Barr’s interest.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="B"><span class="ielts-radio-text"><strong>B</strong> She indicates a potential problem with Barr’s analysis.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="C"><span class="ielts-radio-text"><strong>C</strong> She compares Barr’s conclusion with that of other writers.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="D"><span class="ielts-radio-text"><strong>D</strong> She provides details about the sources Barr used for his research.</span></label></div></div><div class="ielts-standalone-q" data-qnum="29"><div class="ielts-q-header"><strong class="ielts-q-badge">29</strong><span class="ielts-q-title"><span>What does Shester say about chapter six of the book?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="A"><span class="ielts-radio-text"><strong>A</strong> It contains conflicting data.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="B"><span class="ielts-radio-text"><strong>B</strong> It focuses too much on possible trends.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="C"><span class="ielts-radio-text"><strong>C</strong> It is too specialised for most readers.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="D"><span class="ielts-radio-text"><strong>D</strong> It draws on research that is out of date.</span></label></div></div><div class="ielts-standalone-q" data-qnum="30"><div class="ielts-q-header"><strong class="ielts-q-badge">30</strong><span class="ielts-q-title"><span>What does Shester suggest about the chapters focusing on the 1920s building boom?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="A"><span class="ielts-radio-text"><strong>A</strong> The information should have been organised differently.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="B"><span class="ielts-radio-text"><strong>B</strong> More facts are needed about the way construction was financed.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="C"><span class="ielts-radio-text"><strong>C</strong> The explanation that is given for the building boom is unlikely.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="D"><span class="ielts-radio-text"><strong>D</strong> Some parts will have limited appeal to certain people.</span></label></div></div><div class="ielts-standalone-q" data-qnum="31"><div class="ielts-q-header"><strong class="ielts-q-badge">31</strong><span class="ielts-q-title"><span>What impresses Shester the most about the chapter on land values?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="A"><span class="ielts-radio-text"><strong>A</strong> the broad time period that is covered</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="B"><span class="ielts-radio-text"><strong>B</strong> the interesting questions that Barr asks</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="C"><span class="ielts-radio-text"><strong>C</strong> the nature of the research into the topic</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="D"><span class="ielts-radio-text"><strong>D</strong> the recommendations Barr makes for the future</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 32-35                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Do the following statements agree with the claims of the writer in the Reading Passage?</p>
<p><em>In boxes on your answer sheet, write</em></p>
<p><em><strong>YES</strong>                  if the statement agrees with the claims of the writer</em></p>
<p><em><strong>NO</strong>                   if the statement contradicts the claims of the writer</em></p>
<p><em><strong>NOT</strong> <strong>GIVEN</strong>    if it is impossible to say what the writer thinks about this</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="32"><div class="ielts-q-header"><strong class="ielts-q-badge">32</strong><span class="ielts-q-title"><span>The description in the first chapter of how New York probably looked from the air in the early 1600s lacks interest.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="32" name="question_32" value="YES"><span class="ielts-radio-text"><strong>YES</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="32" name="question_32" value="NO"><span class="ielts-radio-text"><strong>NO</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="32" name="question_32" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="33"><div class="ielts-q-header"><strong class="ielts-q-badge">33</strong><span class="ielts-q-title"><span>Chapters two and three prepare the reader well for material yet to come.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="33" name="question_33" value="YES"><span class="ielts-radio-text"><strong>YES</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="33" name="question_33" value="NO"><span class="ielts-radio-text"><strong>NO</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="33" name="question_33" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="34"><div class="ielts-q-header"><strong class="ielts-q-badge">34</strong><span class="ielts-q-title"><span>The biggest problem for many nineteenth-century New York immigrant neighbourhoods was a lack of amenities.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="34" name="question_34" value="YES"><span class="ielts-radio-text"><strong>YES</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="34" name="question_34" value="NO"><span class="ielts-radio-text"><strong>NO</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="34" name="question_34" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="35"><div class="ielts-q-header"><strong class="ielts-q-badge">35</strong><span class="ielts-q-title"><span>In the nineteenth century, New York’s immigrant neighbourhoods tended to concentrate around the harbour.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="35" name="question_35" value="YES"><span class="ielts-radio-text"><strong>YES</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="35" name="question_35" value="NO"><span class="ielts-radio-text"><strong>NO</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="35" name="question_35" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div></div>
