-- Section 1741: Reading Passage 1: Bats to the rescue
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1741, 174, 'reading', 'Reading Passage 1: Bats to the rescue', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-6                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Do the following statements agree with the information given in the Reading Passage?</p>
<p><em>In boxes on your answer sheet, write</em></p>
<p><em><strong>TRUE</strong>               if the statement agrees with the information</em></p>
<p><em><strong>FALSE</strong>              if the statement contradicts the information</em></p>
<p><em><strong>NOT</strong> <strong>GIVEN</strong>    if there is no information on this</em></p>
